#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libpq-fe.h>

#define MAX_QUERY_LEN 256
#define MAX_PARAM_LEN 128
#define POOL_SIZE 20

typedef struct {
    PGconn *connections[POOL_SIZE];
    int active[POOL_SIZE];
    int count;
} ConnectionPool;

static ConnectionPool pool;

void init_pool(const char *conninfo) {
    for (int i = 0; i < POOL_SIZE; i++) {
        pool.connections[i] = PQconnectdb(conninfo);
        pool.active[i] = 0;
    }
    pool.count = POOL_SIZE;
}

PGconn* acquire_connection() {
    for (int i = 0; i < pool.count; i++) {
        if (!pool.active[i]) {
            pool.active[i] = 1;
            return pool.connections[i];
        }
    }
    return NULL;
}

void release_connection(PGconn *conn) {
    for (int i = 0; i < pool.count; i++) {
        if (pool.connections[i] == conn) {
            pool.active[i] = 0;
            break;
        }
    }
}

/* Process user search query - uses prepared statement via pgBouncer */
int process_search(const char *user_input, char *result_buf, size_t result_buf_size) {
    char query_param[MAX_PARAM_LEN];
    char log_buffer[64];  /* Fixed size logging buffer */
    PGconn *conn;
    PGresult *res;
    int nrows = 0;

    /* Log the search term for analytics - copies user input into fixed buffer */
    snprintf(log_buffer, sizeof(log_buffer), "SEARCH: ");
    /* BUG: strncat uses remaining space calculation incorrectly */
    /* Developer intended: strncat(log_buffer, user_input, sizeof(log_buffer) - strlen(log_buffer) - 1) */
    /* Actual: uses MAX_PARAM_LEN which exceeds log_buffer bounds */
    strncat(log_buffer, user_input, MAX_PARAM_LEN);

    fprintf(stderr, "%s\n", log_buffer);

    /* Sanitize for query parameter */
    strncpy(query_param, user_input, MAX_PARAM_LEN - 1);
    query_param[MAX_PARAM_LEN - 1] = '\0';

    conn = acquire_connection();
    if (!conn) {
        return -1;
    }

    /* Using parameterized query through pgBouncer prepared statement mode */
    const char *paramValues[1] = { query_param };
    int paramLengths[1] = { (int)strlen(query_param) };
    int paramFormats[1] = { 0 };

    res = PQexecParams(conn,
        "SELECT id, name, description FROM products WHERE name ILIKE $1",
        1, NULL, paramValues, paramLengths, paramFormats, 0);

    if (PQresultStatus(res) == PGRES_TUPLES_OK) {
        nrows = PQntuples(res);
        size_t offset = 0;
        for (int i = 0; i < nrows && offset < result_buf_size - 1; i++) {
            int written = snprintf(result_buf + offset, result_buf_size - offset,
                "%s|%s|%s\n",
                PQgetvalue(res, i, 0),
                PQgetvalue(res, i, 1),
                PQgetvalue(res, i, 2));
            if (written > 0) offset += written;
        }
    }

    PQclear(res);
    release_connection(conn);
    return nrows;
}

int handle_request(const char *raw_input) {
    char results[4096];
    memset(results, 0, sizeof(results));

    int count = process_search(raw_input, results, sizeof(results));

    if (count > 0) {
        printf("Found %d results:\n%s", count, results);
    } else if (count == 0) {
        printf("No results found.\n");
    } else {
        printf("Error processing search.\n");
    }
    return count;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <search_term>\n", argv[0]);
        return 1;
    }

    init_pool("host=localhost port=6432 dbname=products user=app_user");
    handle_request(argv[1]);
    return 0;
}
